contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public entry performing the test
    function run(uint16 newRate) public payable {
        // no special precondition on c; bound newRate to uint16 domain (already typed)
        // Read observable state before
        uint16 feeBefore = c.feeRate(); if (__ESBMC_reverted()) return;

        // Attempt to call setFeeRate and record whether it reverted
        bool reverted;
        c.setFeeRate(newRate); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read observable state after
        uint16 feeAfter = c.feeRate(); if (__ESBMC_reverted()) return;

        // Assert the general invariant:
        // If call reverted then feeRate must be unchanged. If it did not revert then feeRate must equal newRate and newRate <= 5000.
        assert(
            (reverted && feeAfter == feeBefore) || (!reverted && feeAfter == newRate && newRate <= 5000)
        );
    }

    receive() external payable {}
}

