// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function _run(uint16 newRate) internal {
        uint16 feeBefore;
        try c.feeRate() returns (uint16 __r) { feeBefore = __r; } catch { return; }
        bool reverted;
        try c.setFeeRate(newRate) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint16 feeAfter;
        try c.feeRate() returns (uint16 __r) { feeAfter = __r; } catch { return; }
        assertTrue((reverted && feeAfter == feeBefore) || (!reverted && feeAfter == newRate && newRate <= 5000));
    }

    function testFuzz_run(uint16 newRate) public {
        _run(newRate);
    }

    receive() external payable {}
}
